import{_ as o,D as t,o as n,c as d,j as l,a as e,I as i,w as s,am as r}from"./chunks/framework.DXw8qDd0.js";const q=JSON.parse('{"title":"Codex Skills与Plugins入门","description":"","frontmatter":{"title":"Codex Skills与Plugins入门","time":"2026-06-07T00:00:00.000Z","tags":["codex"]},"headers":[],"relativePath":"笔记/Codex/Codex Skills与Plugins入门.md","filePath":"笔记/Codex/Codex Skills与Plugins入门.md"}'),c={name:"笔记/Codex/Codex Skills与Plugins入门.md"},p=l("h1",{id:"skills-和-plugins-入门",tabindex:"-1"},[e("Skills 和 Plugins 入门 "),l("a",{class:"header-anchor",href:"#skills-和-plugins-入门","aria-label":'Permalink to "Skills 和 Plugins 入门"'},"​")],-1),u=r(`<p>Codex 里的 Skill 和 Plugin 是两种不同层次的扩展能力。</p><hr><h2 id="skill-是什么" tabindex="-1">Skill 是什么 <a class="header-anchor" href="#skill-是什么" aria-label="Permalink to &quot;Skill 是什么&quot;">​</a></h2><p>Skill 可以理解为一份让 Codex 稳定执行重复任务的操作手册。当某个工作流已经很固定，比如&quot;审查 PR&quot;&quot;整理文档&quot;&quot;补案例索引&quot;，就可以把它沉淀成一个 Skill，减少每次重复描述的成本。</p><p>一个 Skill 通常包含：</p><ol><li>一个 SKILL.md 文件：写清触发场景、执行步骤、输出格式和注意事项。</li><li>必要时配套脚本、模板或参考文件：帮助 Codex 更稳定地完成任务。</li></ol><hr><h2 id="plugin-是什么" tabindex="-1">Plugin 是什么 <a class="header-anchor" href="#plugin-是什么" aria-label="Permalink to &quot;Plugin 是什么&quot;">​</a></h2><p>Plugin 更像一种打包和分发机制，用来把可复用工作流、应用集成、MCP 服务配置等能力组合起来，方便在项目或团队中统一安装和使用。</p><p>简单理解：</p><ul><li>Skill 关注&quot;这件事应该怎么做&quot;</li><li>Plugin 关注&quot;把哪些能力打包起来，方便安装和复用&quot;</li></ul><hr><h2 id="它们的关系" tabindex="-1">它们的关系 <a class="header-anchor" href="#它们的关系" aria-label="Permalink to &quot;它们的关系&quot;">​</a></h2><p>你可以把两者想成：</p><ul><li>Skill 是&quot;工作说明书&quot;</li><li>Plugin 是&quot;装着说明书、工具和连接配置的工具箱&quot;</li></ul><p>有些插件里会包含一个或多个 Skills，也可能附带应用集成或 MCP 配置。这样团队在迁移环境时，不用手动一个个配置。</p><hr><h2 id="使用时的提醒" tabindex="-1">使用时的提醒 <a class="header-anchor" href="#使用时的提醒" aria-label="Permalink to &quot;使用时的提醒&quot;">​</a></h2><hr><h2 id="技能目录在哪里" tabindex="-1">技能目录在哪里 <a class="header-anchor" href="#技能目录在哪里" aria-label="Permalink to &quot;技能目录在哪里&quot;">​</a></h2><p>Codex 的技能分布在两个目录下：</p><h3 id="_1-系统内置技能" tabindex="-1">1. 系统内置技能 <a class="header-anchor" href="#_1-系统内置技能" aria-label="Permalink to &quot;1. 系统内置技能&quot;">​</a></h3><p>路径：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>C:\\Users\\&lt;你的用户名&gt;\\.codex\\skills\\</span></span></code></pre></div><p>目录结构：</p><ul><li><code>.system/</code> — 系统自带技能（不要手动删改） <ul><li><code>imagegen</code> — 图片生成</li><li><code>openai-docs</code> — OpenAI 文档查询</li><li><code>skill-creator</code> — 技能创建指南</li><li><code>skill-installer</code> — 技能安装器</li><li><code>plugin-creator</code> — 插件创建器</li></ul></li><li><code>newtype</code> — 内容创作 CLI</li></ul><h3 id="_2-用户-插件安装的技能" tabindex="-1">2. 用户/插件安装的技能 <a class="header-anchor" href="#_2-用户-插件安装的技能" aria-label="Permalink to &quot;2. 用户/插件安装的技能&quot;">​</a></h3><p>路径：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>C:\\Users\\&lt;你的用户名&gt;\\.agents\\skills\\</span></span></code></pre></div><p>典型内容包括：</p><ul><li><code>agent-reach</code> — 网络搜索、社交平台集成</li><li><code>card</code> — 知识卡片生成</li><li><code>gsap</code> — GSAP 动画</li><li><code>hyperframes</code> / <code>hyperframes-cli</code> / <code>hyperframes-registry</code> — 视频合成</li><li><code>lark-im</code> / <code>lark-shared</code> — 飞书集成</li><li><code>remotion-to-hyperframes</code> — Remotion 转 HyperFrames</li><li><code>website-to-hyperframes</code> — 网站转视频</li></ul><h3 id="每个技能文件夹的典型结构" tabindex="-1">每个技能文件夹的典型结构 <a class="header-anchor" href="#每个技能文件夹的典型结构" aria-label="Permalink to &quot;每个技能文件夹的典型结构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>skill-name/</span></span>
<span class="line"><span>  SKILL.md          # 技能说明（核心文件）</span></span>
<span class="line"><span>  scripts/          # 配套脚本（可选）</span></span>
<span class="line"><span>  references/       # 参考文档（可选）</span></span>
<span class="line"><span>  assets/           # 模板、字体、图片等资源（可选）</span></span></code></pre></div><p>其中 SKILL.md 是最关键的文件，Codex 启动技能时会优先读取它。</p><ul><li>插件和技能的具体入口会随版本变化，不要把某个截图里的按钮位置当成永远不变。</li><li>如果插件涉及外部系统、浏览器、邮箱、知识库或项目管理工具，先确认它是只读还是可写。</li><li>涉及安装、写回外部系统或共享给团队时，最好保留人工复核。</li></ul><hr>`,36);function h(k,g,m,_,b,x){const a=t("VPNolebaseInlineLinkPreview");return n(),d("div",null,[p,l("blockquote",null,[l("p",null,[e("来源：CodexGuide - Skills 与 Plugins ("),i(a,{href:"https://codexguide.ai/guide/09-skills-plugins.html",target:"_blank",rel:"noreferrer"},{default:s(()=>[e("https://codexguide.ai/guide/09-skills-plugins.html")]),_:1}),e(")")])]),u,l("blockquote",null,[l("p",null,[e("📎 "),i(a,{href:"/ocdsync/笔记/"},{default:s(()=>[e("📒 返回笔记索引")]),_:1})])])])}const C=o(c,[["render",h]]);export{q as __pageData,C as default};
